#!/bin/bash
# 11-11 07:50~08:15 아침 상태 — 읽기 전용 1회. 서버·DB 에 쓰지 않는다. 재실행·재전송·수집 호출 없음.
set -u
L=/d/tmp/morning-1111
ssh -o BatchMode=yes cat-prod 'echo "crontab $(crontab -l | sha256sum | cut -d" " -f1)"; echo "INSTALLED_SHA $(cat ~/ops-scripts/INSTALLED_SHA)"; echo "daily_check.sh $(sha256sum < ~/ops-scripts/daily_check.sh | cut -d" " -f1)"; echo "daily_checks.sql $(sha256sum < ~/ops-scripts/daily_checks.sql | cut -d" " -f1)"; echo "SID_LEDGER_SHA $(cat ~/ops-scripts/SID_LEDGER_SHA) sid_ledger.sql $(sha256sum < ~/ops-scripts/sid_ledger.sql | cut -d" " -f1)"; cd ~/crypto_trader/AutoTrader && echo "HEAD $(git rev-parse HEAD)"; echo "tracked changes $(git status --porcelain --untracked-files=no | wc -l)"; c=$(docker compose -f docker-compose.prod.yml ps -q backend); docker inspect --format "backend Image={{.Image}} Created={{.Created}} StartedAt={{.State.StartedAt}} RestartCount={{.RestartCount}} Status={{.State.Status}}" $c; ls -l --time-style=full-iso ~/daily-check | tail -4' </dev/null > $L/install_state.txt 2>&1
ssh -o BatchMode=yes cat-prod 'cd ~/crypto_trader/AutoTrader && c=$(docker compose -f docker-compose.prod.yml ps -q backend); z() { docker logs --since 2026-11-10T13:00:00Z $c 2>&1; }; echo "log lines $(z | wc -l)"; echo "first/last: $(z | head -1 | cut -c1-24) / $(z | tail -1 | cut -c1-24)"; echo "ERROR $(z | grep -c " ERROR ") · 획득 실패 $(z | grep -c "Connection is not available") · 누수 경고 $(z | grep -c "Connection leak detection") · unleaked $(z | grep -c unleaked) · Connection reset $(z | grep -c "Connection reset")"; echo "ERROR 로거별:"; z | grep " ERROR " | grep -oE " ERROR +[^ ]+" | sort | uniq -c; z | grep " ERROR " | cut -c1-240' </dev/null > $L/logs_since_2200.txt 2>&1
ssh -o BatchMode=yes cat-prod 'cd ~/crypto_trader/AutoTrader && docker compose -f docker-compose.prod.yml exec -T db psql -X -q -v ON_ERROR_STOP=1 -U trader -d crypto_auto_trader -f -' < $L/morning.sql > $L/db.txt 2>&1
grep -cE '[0-9]{8,10}:[A-Za-z0-9_-]{30,}' $L/install_state.txt $L/logs_since_2200.txt $L/db.txt > $L/token-check.txt
